using Part=BoseWorkbenchPart;
std::size_t end_value(std::string_view s,std::size_t start){
 if(s[start]=='"'){for(std::size_t i=start+1;i<s.size();++i){if(s[i]=='\\'){++i;continue;}if(s[i]=='"')return i+1;}assert(false);}
 if(s[start]=='['||s[start]=='{'){std::vector<char> stack{s[start]};bool quote=false;for(std::size_t i=start+1;i<s.size();++i){if(quote){if(s[i]=='\\')++i;else if(s[i]=='"')quote=false;continue;}if(s[i]=='"'){quote=true;continue;}if(s[i]=='['||s[i]=='{')stack.push_back(s[i]);else if(s[i]==']'||s[i]=='}'){assert(!stack.empty());stack.pop_back();if(stack.empty())return i+1;}}assert(false);}
 const auto end=s.find_first_of(",}] \r\n\t",start);return end==std::string_view::npos?s.size():end;
}
std::string member(std::string_view s,std::string_view name){assert(!s.empty()&&s[0]=='{');std::size_t i=1;while(i<s.size()&&s[i]!='}'){const auto key_end=end_value(s,i);const auto key=s.substr(i+1,key_end-i-2);i=key_end;assert(s[i++]==':');const auto value_end=end_value(s,i);if(key==name)return std::string(s.substr(i,value_end-i));i=value_end;if(s[i]==',')++i;}assert(false);return {};}
std::string first(std::string_view array){assert(array[0]=='['&&array[1]!=']');return std::string(array.substr(1,end_value(array,1)-1));}
std::size_t length(std::string_view array){assert(array[0]=='[');std::size_t i=1,n=0;while(array[i]!=']'){++n;i=end_value(array,i);if(array[i]==',')++i;}return n;}
Part field(std::string key,std::string value){return {std::move(key),"",std::move(value),false};}
Part file(std::string key,std::string value,std::string filename="exact.json"){return {std::move(key),std::move(filename),std::move(value),true};}
BoseWorkbenchResponse okay(const std::vector<Part>& parts){const auto result=execute_bose_workbench(parts);if(result.status!=200)std::cerr<<result.json<<'\n';assert(result.status==200);assert(member(result.json,"executed")=="true"&&member(result.json,"returned")=="true");assert(member(result.json,"error")=="null");assert(length(member(result.json,"native_calls"))==1);assert(member(result.json,"inputs_after_copies")==member(result.json,"inputs_after_native"));return result;}
std::string engine(const std::mt19937& value){std::ostringstream out;out.imbue(std::locale::classic());out<<value;return out.str();}
std::string literal(const std::string& value){assert(value.find_first_of("\"\\\r\n")==std::string::npos);return '"'+value+'"';}
EventLog log(){EventLog value;value.attributes.push_back({"rich-log","retained"});value.metadata.properties.push_back({"property","literal"});for(std::size_t i=0;i<4;++i){Trace trace;trace.case_id="case"+std::to_string(i);trace.case_id_state=FirstClassAttributeState::kPresent;trace.attributes.push_back({"trace","stored"});for(std::size_t j=0;j<2;++j){Event event;event.case_id=trace.case_id;event.activity=std::string(1,static_cast<char>('A'+i*2+j));event.timestamp="1970-01-01T00:00:"+std::string(i<1?"0":"")+std::to_string(i*10+1)+"Z";event.timestamp_state=FirstClassAttributeState::kPresent;event.activity_state=FirstClassAttributeState::kPresent;event.case_id_state=FirstClassAttributeState::kPresent;event.attributes.push_back({"extra","metadata"});trace.events.push_back(std::move(event));}value.traces.push_back(std::move(trace));}return value;}
std::string raw(const EventLog& value){return serialize_embedding_workbench_raw_log_json(value);}
std::string raw_trace(const Trace& trace){EventLog holder;holder.traces.push_back(trace);return first(member(raw(holder),"traces"));}
std::string raw_attrs(const std::vector<EventAttribute>& attrs){EventLog holder;holder.attributes=attrs;return member(raw(holder),"attributes");}
std::string raw_traces(const std::vector<Trace>& traces){EventLog holder;holder.traces=traces;return member(raw(holder),"traces");}
std::vector<Part> source(std::string op,const EventLog& value){return {field("operation",std::move(op)),field("source_format","raw_log"),file("source_file",raw(value))};}
const std::string small_options=R"({"sub_log_size":2,"window_size":1,"num_permutations":1,"threshold":1.1,"max_no_change_points":1})";
const std::string rng_seed=R"({"constructor":"seed32","seed":0})";
void all_twenty_five_declarations(){
 auto input=log();auto table=event_data_to_table(EventDataView(input));const auto table_raw=serialize_embedding_workbench_table_json(table);std::size_t calls=0;
 for(const auto* op:{"table_apply","log_apply","dispatch_table","dispatch_log"})for(bool caller:{false,true}){const bool is_table=std::string(op).find("table")!=std::string::npos;auto parts=source(op,input);parts[1]=field("source_format",is_table?"raw_table":"raw_log");parts[2]=file("source_file",is_table?table_raw:raw(input));parts.push_back(field("options_json",small_options));if(caller)parts.push_back(field("rng_json",rng_seed));const auto response=okay(parts);++calls;const auto result=member(response.json,"native_result");assert(length(member(result,"returned_tables"))==2);assert(member(result,"change_timestamps")=="[21.0]"&&member(result,"p_values")=="[1.0]");const auto output_table=parse_embedding_workbench_table_json(first(member(result,"returned_tables")));assert(output_table.rows.size()==4&&output_table.columns.size()==3&&output_table.index);const auto original=member(member(response.json,"inputs_after_native"),"source");assert(is_table?serialize_embedding_workbench_table_json(parse_embedding_workbench_table_json(original))==table_raw:raw(parse_embedding_workbench_raw_log_json(original))==raw(input));if(caller){std::mt19937 expected(0);ConceptDriftTableOptions options;options.sub_log_size=2;options.window_size=1;options.num_permutations=1;options.threshold=1.1;options.max_no_change_points=1;if(is_table)(void)apply_concept_drift_table(table,options,expected);else(void)apply_concept_drift_log(input,options,expected);const auto state=member(response.json,"rng");assert(member(state,"after")==literal(engine(expected)));assert(member(state,"options_seed_active")=="false");}}
 for(const auto* op:{"activities_default","activities","features_log","split_sublogs","detect_log"}){auto parts=source(op,input);if(std::string(op)=="split_sublogs")parts.push_back(field("parameters_json",R"({"sub_log_size":3,"keep_leftover":false})"));if(std::string(op)=="detect_log")parts.push_back(field("options_json",R"({"sub_log_size":2,"window_size":1,"num_permutations":1,"threshold":1.0,"include_timestamps":true})"));const auto response=okay(parts);++calls;if(std::string(op).starts_with("activities"))assert(member(response.json,"native_result")==R"(["A","B","C","D","E","F","G","H"])");if(std::string(op)=="split_sublogs"){const auto parsed=parse_embedding_workbench_raw_log_json(first(member(response.json,"native_result")));assert(parsed.traces.size()==3&&parsed.metadata==input.metadata&&parsed.attributes==input.attributes);}if(std::string(op)=="detect_log"){const auto result=member(response.json,"native_result");const auto parsed=parse_embedding_workbench_raw_log_json(first(member(result,"cumulative_sublogs")));assert(parsed.traces.size()==2&&parsed.metadata==input.metadata);assert(length(member(result,"sublogs"))==2);assert(member(result,"activity_attribute")=="\"concept:name\"");}}
 const auto t=raw_trace(input.traces.front());const auto ts=raw_traces(input.traces);const auto a=raw_attrs({EventAttribute{"","A"},EventAttribute{"","B"}});const std::string typed_traces='['+a+','+a+','+a+','+a+']';
 for(const auto* op:{"typed_activities","features_traces_default","features_traces","typed_features","follows","typed_follows"}){const std::string operation=op;const bool typed=operation.starts_with("typed");const bool follows=operation.ends_with("follows");std::vector<Part> parts{field("operation",operation),file(follows?"trace_file":"traces_file",typed?(follows?a:typed_traces):(follows?t:ts))};if(operation!="typed_activities")parts.push_back(file("alphabet_file",typed?a:(follows?R"(["A","B"])":R"(["A","B","C","D","E","F","G","H"])")));const auto response=okay(parts);++calls;if(operation=="follows")assert(member(response.json,"native_result")==R"([["A","B"]])");if(operation=="typed_activities")assert(length(member(response.json,"native_result"))==2);}
 for(const auto* op:{"permutation","detect_traces","detect_typed_traces"})for(bool caller:{false,true}){const std::string operation=op;std::vector<Part> parts{field("operation",operation)};if(operation=="permutation"){parts.push_back(file("first_file","[[1.0,0.0],[0.0,1.0]]"));parts.push_back(file("second_file","[[0.0,0.0],[1.0,1.0]]"));parts.push_back(field("parameters_json",R"({"num_permutations":3,"seed":18446744073709551615})"));}else{parts.push_back(file("traces_file",operation=="detect_traces"?R"([["A","B"],["A","B"],["C","D"],["C","D"]])":typed_traces));parts.push_back(field("options_json",small_options));}if(caller)parts.push_back(field("rng_json",rng_seed));const auto response=okay(parts);++calls;if(operation!="permutation")assert(length(member(member(response.json,"native_result"),"sublogs"))==2);if(caller)assert(member(member(response.json,"rng"),"before")!=member(member(response.json,"rng"),"after"));}
 assert(calls==25);
}
void exact_options_and_native_rejections(){
 auto parts=source("log_apply",log());parts.push_back(field("options_json",R"({"sub_log_size":-9223372036854775808,"window_size":9223372036854775807,"num_permutations":-9223372036854775808,"max_no_change_points":-9223372036854775808,"threshold":"NaN","seed":18446744073709551615,"case_id_attribute":{"native_bytes":"hex-v1","data":"ff00"}})"));auto response=okay(parts);const auto stored=member(response.json,"configured_options");assert(member(stored,"seed")=="18446744073709551615");assert(member(stored,"sub_log_size")=="-9223372036854775808");assert(member(stored,"threshold")=="\"NaN\"");assert(member(response.json,"native_result")==R"({"change_timestamps":[],"p_values":[],"returned_tables":[]})");
 for(const auto* option:{R"({"sub_log_size":9223372036854775808})",R"({"seed":18446744073709551616})",R"({"threshold":true})",R"({"sub_log_size":1,"sub_log_size":2})",R"({"unknown":0})"}){auto p=source("log_apply",log());p.push_back(field("options_json",option));const auto failed=execute_bose_workbench(p);assert(failed.status==400&&member(failed.json,"executed")=="false");assert(member(member(failed.json,"error"),"phase")=="\"configuration_error\"");}
 auto invalid=source("dispatch_log",EventLog{});invalid.push_back(field("parameters_json",R"({"variant":-2147483648})"));invalid.push_back(field("rng_json",rng_seed));response=execute_bose_workbench(invalid);assert(response.status==400&&member(response.json,"executed")=="true");assert(member(member(response.json,"rng"),"before")==member(member(response.json,"rng"),"after"));assert(member(member(response.json,"error"),"phase")=="\"native_error\"");
 auto unsigned_threshold=source("detect_log",log());unsigned_threshold.push_back(field("options_json",R"({"threshold":1.1})"));response=execute_bose_workbench(unsigned_threshold);assert(response.status==400&&member(response.json,"executed")=="true"&&member(response.json,"returned")=="false");assert(member(member(response.json,"error"),"phase")=="\"native_error\"");assert(member(member(response.json,"error"),"message")=="\"concept drift: threshold must be finite and in [0,1]\"");
 auto unsigned_bad=source("detect_log",log());unsigned_bad.push_back(field("options_json",R"({"window_size":-1})"));response=execute_bose_workbench(unsigned_bad);assert(response.status==400&&member(response.json,"executed")=="false");
 std::vector<Part> perm={field("operation","permutation"),file("first_file","[[1.0,2.0]]"),file("second_file","[[3.0,4.0]]"),field("parameters_json",R"({"num_permutations":-1})"),field("rng_json",rng_seed)};response=okay(perm);assert(member(response.json,"native_result")=="-0.0");assert(member(member(response.json,"rng"),"before")==member(member(response.json,"rng"),"after"));perm[1]=file("first_file","[[1.0],[1.0,2.0]]");response=execute_bose_workbench(perm);assert(response.status==400&&member(response.json,"executed")=="true");
}
void caller_engine_roundtrip_and_failure(){
 std::vector<Part> p={field("operation","permutation"),file("first_file","[[1.0],[2.0]]"),file("second_file","[[3.0],[4.0]]"),field("parameters_json",R"({"num_permutations":3,"seed":18446744073709551615})"),field("rng_json",R"({"constructor":"seed_seq_words","words":[0,4294967295,17]})")};
 const auto response=okay(p);std::vector<std::uint32_t> words{0,4294967295U,17};std::seed_seq sequence(words.begin(),words.end());std::mt19937 expected(sequence);assert(member(member(response.json,"rng"),"before")==literal(engine(expected)));const auto probability=concept_drift_permutation_test({{1},{2}},{{3},{4}},3,expected);const auto after=member(member(response.json,"rng"),"after");assert(after==literal(engine(expected)));assert(std::stod(member(response.json,"native_result"))==probability);
 p.back()=field("rng_json","{\"constructor\":\"state_text\",\"state\":"+after+'}');const auto continued=okay(p);assert(member(member(continued.json,"rng"),"before")==after);(void)concept_drift_permutation_test({{1},{2}},{{3},{4}},3,expected);assert(member(member(continued.json,"rng"),"after")==literal(engine(expected)));
 for(const auto* bad:{R"({"constructor":"seed32","seed":4294967296})",R"({"constructor":"seed_seq_words","words":[-1]})",R"({"constructor":"state_text","state":"not a state"})",R"({"constructor":"unavailable"})"}){p.back()=field("rng_json",bad);const auto failure=execute_bose_workbench(p);assert(failure.status==400&&member(failure.json,"executed")=="false");}
 p.back()=field("rng_json","{\"constructor\":\"state_text\",\"state\":"+literal(engine(expected)+" trailing")+'}');assert(execute_bose_workbench(p).status==400);
}
