 p.push_back(field("construction_copies_json",R"([{"from":{"owner":"traces","path":[0,0]},"to":{"owner":"traces","path":[0,1]},"member":"typed_value"}])"));response=okay(p);assert(length(member(response.json,"native_result"))==1);assert(length(member(member(response.json,"identity_proof"),"steps"))==1);
 p.back()=field("construction_copies_json",R"([{"from":{"owner":"traces","path":[99]},"to":{"owner":"traces","path":[0,1]},"member":"attribute"}])");response=execute_bose_workbench(p);assert(response.status==400&&member(response.json,"executed")=="false");assert(member(member(response.json,"error"),"phase")=="\"construction_error\"");
 auto source_parts=source("table_apply",log());response=execute_bose_workbench(source_parts);assert(response.status==400&&member(response.json,"executed")=="false");source_parts.push_back(field("source_shape","table"));source_parts.push_back(field("options_json",small_options));response=okay(source_parts);assert(member(member(member(response.json,"input_context"),"source"),"original_kind")=="\"log\"");assert(member(member(member(response.json,"input_context"),"source"),"selected_kind")=="\"table\"");
